import type { Verse } from '../types/verse';
import { BIBLE_BOOKS, referenceBookName } from './bibleBooks';
import { CURATED_VERSES } from './curatedVerses';
import type { Translation } from './translations';
// Generated by scripts/build-bible.ts: { [translation]: { [verseId]: text } }
import curatedText from './curatedText.json';

const TEXT = curatedText as Record<Translation, Record<string, string>>;

/** The built-in library, worded in the given translation. */
export function curatedVerses(translation: Translation): Verse[] {
  return CURATED_VERSES.map((cv) => {
    const book = BIBLE_BOOKS.find((b) => b.code === cv.book)!;
    return {
      id: cv.id,
      reference: `${referenceBookName(book)} ${cv.chapter}:${cv.verses}`,
      book: book.name,
      chapter: cv.chapter,
      verseNum: cv.verses,
      text: TEXT[translation][cv.id],
      category: cv.category,
      translation,
      tags: cv.tags,
    };
  });
}

export const FIRST_VERSE_ID = CURATED_VERSES[0].id;
